with flattened_attrs as (select id, service, host, level, latency_ms, status_code, context, context['version'] as version, size(context) as num_context, cast((status_code & 1) != 0 as int) as is_flagged, context['region'] as region from app_logs) select id, service, host, level, latency_ms, status_code, context, version, num_context, is_flagged, region, lag(num_context, 2, 0) over (order by latency_ms, id) as prev_num_context, round(latency_ms / sum(latency_ms) over (partition by level), 4) as latency_ms_share from flattened_attrs;
